cat > docker-compose.yml <<'YAML'
services:
  healthchecks:
    image: healthchecks/healthchecks:v4.3
    restart: unless-stopped
    environment:
      DB: postgres
      DB_HOST: ${PGHOST}
      DB_PORT: ${PGPORT}
      DB_NAME: ${PGDATABASE}
      DB_USER: ${PGUSER}
      DB_PASSWORD: [REDACTED:value]}
      DB_SSLMODE: prefer
      SECRET_KEY: [REDACTED:value]}
      DEBUG: "False"
      SITE_ROOT: ${SITE_ROOT}
      ALLOWED_HOSTS: ${ALLOWED_HOSTS}
      SITE_NAME: ${SITE_NAME:-Healthchecks}
      REGISTRATION_OPEN: "False"
      SHELL_ENABLED: "False"
      INTEGRATIONS_ALLOW_PRIVATE_IPS: "False"
      SECURE_PROXY_SSL_HEADER: HTTP_X_FORWARDED_PROTO,https
      DEFAULT_FROM_EMAIL: ${DEFAULT_FROM_EMAIL:-healthchecks@example.org}
      EMAIL_HOST: ${EMAIL_HOST:-}
      EMAIL_PORT: ${EMAIL_PORT:-587}
      EMAIL_HOST_USER: ${EMAIL_HOST_USER:-}
      EMAIL_HOST_PASSWORD: «REDACTED:assigned:fc6b62cc»}
      EMAIL_USE_TLS: "True"
    ports:
      - "8000:8000"
YAML
